def mayor_racha(lista: list) -> tuple | None:
    """
    Encuentra la racha más larga de elementos consecutivos iguales.
    Devuelve la tupla (elemento, longitud) en caso de empate,
    la primera racha encontrada.
    Si la lista está vacía, devuelve None.
    """
    if not lista:
        return None

    max_racha = (lista[0], 1)
    current_racha = (lista[0], 1)

    for i in range(1, len(lista)):
        if lista[i] == lista[i - 1]:
            current_racha = (lista[i], current_racha[1] + 1)
        else:
            if current_racha[1] > max_racha[1]:
                max_racha = current_racha
            current_racha = (lista[i], 1)

    if current_racha[1] > max_racha[1]:
        max_racha = current_racha

    return max_racha

def a_snake(s: str) -> str:
    """
    Convierte una cadena de texto de camelCase o PascalCase a snake_case.
    Todo en minusculas y un guion bajo antes de cada mayuscula interna.
    No empieza con guion bajo.
    """
    if not s:
        return ""
    return s[0].lower() + "_".join(word.lower() for word in s.split("_"))

def primos(n: int) -> list[int]:
    """Devuelve la lista ordenada de todos los números primos menores o iguales a n."""
    if n < 2:
        return []
    return [i for i in range(2, n + 1) if all(i % j != 0 for j in range(2, int(i**0.5) + 1))]

def mcd(a, b):
    """
    Devuelve el máximo común divisor de dos enteros no negativos.
    El mcd de un número con 0 es ese número.
    """
    if b == 0:
        return a
    while b != 0:
        a, b = b, a % b
    return a

def balanceado(texto: str) -> bool:
    """
    Verifica si los paréntesis, corchetes y llaves del texto están correctamente
    balanceados y anidados.

    Args:
        texto: La cadena de texto a verificar.

    Returns:
        True si los paréntesis, corchetes y llaves están balanceados,
        False si no lo son.
    """
    if not texto:
        return True

    open_parens = 0
    open_brackets = 0
    open_braces = 0

    for char in texto:
        if char == '(':
            open_parens += 1
        elif char == '[':
            open_brackets += 1
        elif char == ']':
            if open_brackets == 0:
                return False
            open_brackets -= 1
        elif char == '{':
            open_braces += 1
        elif char == '}':
            if open_braces == 0:
                return False
            open_braces -= 1

    return open_parens == 0 and open_brackets == 0 and open_braces == 0

def formatear_bytes(n: int) -> str:
    """
    Convierte una cantidad de bytes a texto legible usando base 1024
    y las unidades B, KB, MB, GB.

    Los bytes se muestran sin decimales y las demas unidades con UN decimal.

    Args:
        n: Cantidad de bytes a convertir.

    Returns:
        String con la representación en texto legible.
    """
    if n < 0:
        return "Error: valor negativo"

    if n == 0:
        return "0 B"

    unidades = ["B", "KB", "MB", "GB"]

    for i in range(4):
        if n >= 1024 ** i:
            valor = n / (1024 ** i)
            if i == 0:
                return f"{int(valor)} B"
            else:
                return f"{valor:.1f} {unidades[i]}"

    return f"{n} B"
